#include <iostream>
#include <algorithm>
using namespace std;

bool next_permutation(int idx[], int n) {
	for (int i = n - 1; i >= 1; i--) {
		if (idx[i] > idx[i-1]) {
			swap(idx[i], idx[i-1]);
			sort(idx + i, idx + n);
			return true;
		}
	}
	return false;
}

int main() {
	int n, a, b;
	scanf("%d\n%d\n%d", &n, &a, &b);
	int frames[6], idxs[6];
	for (int i = 0; i < 6; i++) {
		if (i < 4) {
			frames[i] = a;
		} else {
			frames[i] = b;
		}
		idxs[i] = i;
	}

	int bestAnswer = 6;
	do {
		int count = 0, leftover = 0;
		for (int i = 0; i < 6; i++) {
			if (leftover < frames[idxs[i]]) {
				count++;
				leftover = n;
			}
			leftover -= frames[idxs[i]];
		}
		if (count < bestAnswer) {
			bestAnswer = count;
		}
	} while (next_permutation(idxs, 6));

	cout << bestAnswer << endl;
	return 0;
}

